import fs from 'fs/promises';
import path from 'path';
import { parseS3Error } from '../api/error-response.js';
import * as log from './log.js';
/**
 * Retry configuration
 */ const MAX_RETRIES = 3;
const INITIAL_RETRY_DELAY = 1000 // 1 second
;
/**
 * Sleep for specified milliseconds
 */ function sleep(ms) {
    return new Promise((resolve)=>setTimeout(resolve, ms));
}
/** Common MIME types for web assets, keyed by file extension */ const MIME_TYPES = {
    '.avif': 'image/avif',
    '.css': 'text/css',
    '.csv': 'text/csv',
    '.eot': 'application/vnd.ms-fontobject',
    '.gif': 'image/gif',
    '.html': 'text/html',
    '.ico': 'image/x-icon',
    '.jpeg': 'image/jpeg',
    '.jpg': 'image/jpeg',
    '.js': 'application/javascript',
    '.json': 'application/json',
    '.map': 'application/json',
    '.meta': 'application/json',
    '.mjs': 'application/javascript',
    '.mp4': 'video/mp4',
    '.otf': 'font/otf',
    '.pdf': 'application/pdf',
    '.png': 'image/png',
    '.rsc': 'text/x-component',
    '.svg': 'image/svg+xml',
    '.ttf': 'font/ttf',
    '.txt': 'text/plain',
    '.wasm': 'application/wasm',
    '.webm': 'video/webm',
    '.webp': 'image/webp',
    '.woff': 'font/woff',
    '.woff2': 'font/woff2',
    '.xml': 'application/xml',
    '.zip': 'application/zip'
};
/**
 * Check if a signed URL is a mock URL
 */ function isMockUrl(signedUrl) {
    return signedUrl.includes('X-Amz-Signature=mock');
}
/**
 * Upload a file to S3 using a signed URL
 *
 * Retries up to 3 times with exponential backoff
 *
 * @param filePath - Absolute path to file to upload
 * @param signedUrl - Signed S3 upload URL
 * @throws Error if upload fails after retries
 */ export async function uploadFile(filePath, signedUrl, contentType) {
    // Skip actual upload for mock URLs
    if (isMockUrl(signedUrl)) {
        log.debug(`Mock upload detected for ${path.basename(filePath)}`);
        // Verify file exists
        const stats = await fs.stat(filePath);
        // Simulate upload latency based on file size
        // lambda.zip: ~1-2 seconds, small files: 50-150ms
        const isLargeFile = stats.size > 1024 * 1024 // > 1MB
        ;
        const latency = isLargeFile ? 1000 + Math.random() * 1000 // 1-2 seconds for large files
         : 50 + Math.random() * 100 // 50-150ms for small files
        ;
        await sleep(latency);
        return;
    }
    const fileBuffer = await fs.readFile(filePath);
    let lastError = null;
    for(let attempt = 0; attempt < MAX_RETRIES; attempt++){
        try {
            const ext = path.extname(filePath).toLowerCase();
            const determinedContentType = contentType ?? MIME_TYPES[ext];
            const response = await fetch(signedUrl, {
                body: fileBuffer,
                headers: determinedContentType ? {
                    'Content-Type': determinedContentType
                } : {},
                method: 'PUT'
            });
            if (response.ok) {
                return; // Success
            }
            lastError = new Error(await parseS3Error({
                context: `upload ${path.basename(filePath)}`,
                response
            }));
        } catch (error) {
            lastError = error instanceof Error ? error : new Error('Unknown error');
        }
        // Wait before retry (exponential backoff)
        if (attempt < MAX_RETRIES - 1) {
            await sleep(INITIAL_RETRY_DELAY * Math.pow(2, attempt));
        }
    }
    throw lastError || new Error('Upload failed after retries');
}
/**
 * Upload Lambda code zip to S3
 *
 * @param zipPath - Path to lambda.zip
 * @param signedUrl - Signed S3 upload URL
 */ export async function uploadLambdaZip(zipPath, signedUrl) {
    await uploadFile(zipPath, signedUrl, 'application/zip');
}
/**
 * Upload static assets to S3 in parallel
 *
 * Uploads up to 5 files concurrently
 *
 * @param projectPath - Path to project root
 * @param assetUrls - Map of asset paths to signed URLs
 * @param onProgress - Optional callback for progress updates (uploaded, total)
 * @returns Upload results with counts
 */ export async function uploadStaticAssets(params) {
    const { assetUrls, onProgress, pathMap, projectPath } = params;
    const results = {
        assetsFailed: 0,
        assetsUploaded: 0,
        lambdaUploaded: false,
        totalBytesUploaded: 0
    };
    const assetPaths = Object.keys(assetUrls);
    if (assetPaths.length === 0) {
        return results;
    }
    // Upload assets with limited concurrency
    const CONCURRENCY = 5;
    for(let i = 0; i < assetPaths.length; i += CONCURRENCY){
        const batch = assetPaths.slice(i, i + CONCURRENCY);
        await Promise.all(batch.map(async (assetPath)=>{
            try {
                // Resolve filesystem path: use pathMap if available, else default _next/ → .next/
                const fsPath = pathMap?.[assetPath] ?? assetPath.replace(/^_next\//, '.next/');
                const fullPath = path.join(projectPath, fsPath);
                const signedUrl = assetUrls[assetPath];
                const contentType = MIME_TYPES[path.extname(assetPath).toLowerCase()];
                await uploadFile(fullPath, signedUrl, contentType);
                results.assetsUploaded++;
                // Track bytes uploaded
                const stats = await fs.stat(fullPath);
                results.totalBytesUploaded += stats.size;
                // Report progress
                onProgress?.(results.assetsUploaded, assetPaths.length);
                return undefined;
            } catch (error) {
                results.assetsFailed++;
                log.debug(`Failed to upload ${assetPath}: ${error instanceof Error ? error.message : 'Unknown error'}`);
                return undefined;
            }
        }));
    }
    return results;
}
